"""Search landing pages: public page content, omitted from the main navigation."""
PAGES=[
 {'slug':'hindi-dubbed-anime','title':'Watch Hindi Dubbed Anime Online','intro':'Explore anime editions with confirmed Hindi audio and watch official YouTube uploads inside AniLove India.','paragraphs':[('Choose Hindi audio by edition','Hindi dubbing belongs to a particular upload, rather than every version of an anime. The titles below have at least one Hindi-audio edition in our checked catalogue. Open the title, choose its Hindi season tab, then select an episode. SPY x FAMILY is a useful starting point: its available Hindi seasons are listed separately so you can continue the right story.'),('Pick an episode without an account','AniLove does not require a separate account to open a title or load its player. Episodes remain on YouTube and use its standard player, including fullscreen controls. If an upload is unavailable in your region, report the episode to Nitesh on WhatsApp. A Hindi-audio label does not certify playback from every Indian connection.')],'faqs':[('Can I watch anime in Hindi here?','Yes. The collection below lists titles with at least one checked Hindi-audio edition. Select the Hindi season on its title page.'),('Are all seasons in Hindi?','Languages are listed per season or edition. A Hindi edition does not mean that every season is dubbed.'),('How do I request a missing Hindi dub?','Search for the title. If it is missing, use the request form to open a message to Nitesh on WhatsApp.')],'kind':'hindi-anime'},
 {'slug':'english-subbed-anime','title':'Watch Anime with English Subtitles','intro':'Find official Japanese-audio anime editions with English subtitles and choose from the actual uploaded episodes.','paragraphs':[('Check the subtitle label before you play','An English title alone does not establish English subtitles. This collection uses the subtitle-language fields of checked anime editions. On the title page, choose the relevant season or compilation and open an upload. YouTube controls the caption menu; turn English captions on in the player when the source provides a selectable track.'),('Series uploads and long compilations','Some anime arrive as individual episode videos. Others are long official compilation uploads. Numbered buttons correspond to actual individual videos, while Play All identifies a compilation. Use the timeline for a long upload. Listed upload counts are not a promise of complete seasons, and subtitle or regional availability can change after a source check.')],'faqs':[('Which anime have English subtitles?','The titles below include at least one edition marked with English subtitles. Subtitle languages appear with each season.'),('Can I select a particular episode?','Yes, when the official source has separate checked episode uploads. Compilations have a Play All option.'),('Are fan-subbed reuploads included?','The playable catalogue uses source-reviewed official channel uploads.')],'kind':'sub-anime'},
 {'slug':'anime-movies-english-subtitles','title':'Watch Anime Movies with English Subtitles','intro':'Choose feature-length official anime uploads with English subtitles, then play the film on AniLove India.','paragraphs':[('A film collection with actual players','The films below each have a checked full-length source upload and an English-subtitled edition in the catalogue. The Mobile Suit Gundam films are available from GUNDAM CHANNEL INTL in Japanese with English caption tracks. Open a movie and choose Watch full movie to reach its dedicated player page.'),('Know the edition you are watching','Audio and subtitles are separate labels. An English dub is not the same edition as a Japanese film with English subtitles. This collection filters for subtitles; the broader Anime Movies category also includes other audio editions. The uploader controls how long a film stays available, whether embedding is enabled and which regions can watch it.')],'faqs':[('Are these full movies or trailers?','Each listed playable movie is backed by a checked feature-length upload. Trailers are not substituted for films.'),('How do I turn on English captions?','Open the YouTube player controls and choose an English caption track where the uploaded edition provides one.'),('Are all Gundam films available here?','Only the specific checked uploads in this collection are listed; this is not the complete Gundam film catalogue.')],'kind':'sub-films'},
 {'slug':'south-indian-movies-hindi-dubbed','title':'Watch South Indian Movies in Hindi','intro':'Browse checked Hindi-dubbed full movies from official YouTube sources, with playback on AniLove India.','paragraphs':[('Hindi editions from official uploaders','Goldmines publishes Hindi editions of South Indian films on its official channel. This collection lists the full-length uploads we have checked from that source. A channel may upload an older film again as a new YouTube release, so a recent upload does not necessarily mean a newly produced film. The exact source video appears on the player page.'),('From movie card to full film','Open a title and use Watch full movie. The video loads only after you press Play; there is no need to leave AniLove for another streaming service. Source checks cover channel identity, runtime, embedding metadata and India country metadata. Actual playback still depends on YouTube and the uploader’s current restrictions.')],'faqs':[('Can I watch the Hindi-dubbed full movie here?','Open a listed film and press Play on its dedicated page to load the official YouTube embed.'),('Does a 2026 upload mean a 2026 film?','No. Upload dates and film release dates are different; older films can receive new Hindi uploads.'),('Where do missing movie requests go?','The request form opens WhatsApp to Nitesh at +91 79748 23298 with your entered details.')],'kind':'south-hindi'},
 {'slug':'korean-dramas-english-subtitles','title':'Watch Korean Dramas with English Subtitles','intro':'Explore official Korean drama uploads with English subtitles, including checked KBS WORLD TV episodes.','paragraphs':[('Start with the uploaded edition','This collection focuses on Korean drama editions whose source metadata or uploaded title confirms English subtitles. Open a drama to see its available episodes. KBS WORLD TV provides the source for the checked drama uploads in this catalogue. Popular titles and older drama specials can remain useful starting points even when they are not new television releases.'),('Follow the episode list accurately','Episode numbers reflect actual checked source videos. A list can contain gaps when an episode was not found or did not pass checks. A drama special can also be a standalone long episode. Neither a source playlist nor the number of listed videos automatically certifies a whole season. Send a WhatsApp report if an episode is missing or its captions stop working.')],'faqs':[('Are the dramas dubbed in Hindi?','The editions in this collection use Korean audio with English subtitles unless a separate edition explicitly says otherwise.'),('Can I watch a complete K-drama season?','Check the title’s episode list. Completion is not certified for every title; available uploads are shown individually.'),('Can I watch without registering on AniLove?','AniLove requires no separate account to open a title and load its official player.')],'kind':'sub-drama'},
 {'slug':'anime-seasons-episodes','title':'Browse Anime Seasons and Episodes Online','intro':'Find the right anime season, story arc or compilation, then choose an actual uploaded episode.','paragraphs':[('Seasons stay separate','Anime franchises can have several numbered seasons, named story arcs and language editions. AniLove keeps these as separate season or edition tabs. SPY x FAMILY, Classroom of the Elite and JoJo’s Bizarre Adventure illustrate why the distinction matters: selecting a tab lets you browse the uploads associated with that part of the story.'),('Continue from the right upload','Choose a numbered episode button or thumbnail to open its dedicated page. Previous and Next follow the listed source uploads, including split or combined uploads where applicable. A combined video keeps its source range, and a long compilation uses Play All. Your last opened episode and watchlist can be saved on this browser; they do not sync to another device.')],'faqs':[('How do I change the anime season?','Open a title and choose a season tab above its episode list, or start from the Seasons page.'),('Why do some buttons show a range or letter?','The source may combine several episodes or split an episode into multiple videos. The controls preserve those distinctions.'),('Does Play All mean individual episodes are missing?','Play All identifies one long compilation upload. Use its player timeline to move through that edition.')],'kind':'seasons'}
]
def select(t,kind):
 if kind=='hindi-anime':return t['category']=='anime-series'and any(s['audio_language']=='Hindi'for s in t['seasons'])
 if kind=='sub-anime':return t['category']=='anime-series'and any('English'in s.get('subtitle_languages',[])for s in t['seasons'])
 if kind=='sub-films':return t['category']=='anime-movies'and any('English'in s.get('subtitle_languages',[])for s in t['seasons'])
 if kind=='south-hindi':return t['provider']=='Goldmines'
 if kind=='sub-drama':return t['category']=='k-dramas'and any('English'in s.get('subtitle_languages',[])for s in t['seasons'])
 if kind=='seasons':return t['category']=='anime-series'and len(t['seasons'])>1
 return False

def build_landings(page,cards,titles,esc,base):
 for item in PAGES:
  path='/discover/'+item['slug']+'/'
  ts=[t for t in titles if select(t,item['kind'])]
  if not ts:continue
  body='<article class="prose"><p class="eyebrow">ANILOVE INDIA · WATCHING GUIDE</p><h1>'+esc(item['title'])+'</h1><p class="lead">'+esc(item['intro'])+'</p>'
  for heading,text in item['paragraphs']:body+='<h2>'+esc(heading)+'</h2><p>'+esc(text)+'</p>'
  body+='</article><section class="section"><div class="section-heading"><h2>Choose a title</h2></div>'+cards(ts)+'</section><article class="prose"><h2>Questions about this collection</h2>'
  for q,a in item['faqs']:body+='<details open><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>'
  body+='<p><a href="/search/">Search all titles</a> · <a href="/seasons/">Browse seasons</a> · <a href="/contact/">Request on WhatsApp</a></p></article>'
  schema={'@context':'https://schema.org','@graph':[{'@type':'CollectionPage','@id':base+path,'name':item['title'],'description':item['intro'],'url':base+path,'inLanguage':'en-IN','mainEntity':{'@type':'ItemList','numberOfItems':len(ts),'itemListElement':[{'@type':'ListItem','position':i+1,'url':base+'/title/'+t['id']+'/','name':t['title']}for i,t in enumerate(ts)]}},{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}}for q,a in item['faqs']]},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'AniLove India','item':base+'/'},{'@type':'ListItem','position':2,'name':item['title'],'item':base+path}]}]}
  page(path,item['title'],body,item['intro'],schema)
